// Создаёт или перестраивает сцену выбранного корабля.
const api = game.modules.get("skyplane-combat-reverse").api;
const ships = game.actors.filter((actor) => actor.type === "skyplane-combat-reverse.ship");
if (!ships.length) return ui.notifications.warn("Нет ни одного неболёта.");
const options = ships.map((ship) => `<option value="${ship.uuid}">${foundry.utils.escapeHTML(ship.name)}</option>`).join("");
const uuid = await foundry.applications.api.DialogV2.prompt({
  window: { title: "Развернуть корабль" },
  content: `<div class="form-group"><label>Корабль</label><select name="ship">${options}</select></div>`,
  ok: { label: "Развернуть", callback: (event, button) => button.form.elements.ship.value },
  rejectClose: false
});
if (uuid) (await api.deployShip(uuid))?.view();
